mapper.select:
SELECT * FROM ( SELECT MEMBER_NO AS "memberNo", EMAIL AS "memberEmail", NICKNAME AS "memberNickname", NAME AS "memberName", PHONE AS "memberPhone", PROFILE_IMAGE AS "memberProfileImg", MEMBER_TYPE AS "memberRole", STATUS AS "memberStatus", TO_CHAR(CREATED_AT, 'YYYY-MM-DD') AS "createdAt", ROW_NUMBER() OVER (ORDER BY MEMBER_NO ASC) AS RN FROM MEMBER WHERE 1=1
AND NICKNAME LIKE '%' || #{search} || '%'
AND EMAIL LIKE '%' || #{search} || '%'
AND NAME LIKE '%' || #{search} || '%'
AND (NICKNAME LIKE '%' || #{search} || '%' OR EMAIL LIKE '%' || #{search} || '%')
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.update:
UPDATE MEMBER
SET STATUS = #{status}, UPDATED_AT = SYSDATE
WHERE MEMBER_NO = #{memberNo}

mapper.select:
SELECT * FROM ( SELECT C.COMPANION_NO AS "companionNo", C.TITLE AS "title", C.STATUS AS "status", C.MAX_MEMBERS AS "maxMembers", TO_CHAR(C.TRAVEL_DATE) AS "travelDate", TO_CHAR(C.CREATED_AT, 'YYYY-MM-DD') AS "createdAt", M.NICKNAME AS "authorNickname", M.MEMBER_NO AS "memberNo", (SELECT COUNT(*) FROM COMPANION_JOIN J WHERE J.COMPANION_NO = C.COMPANION_NO AND J.STATUS IN ('W','A') ) AS "currentMembers", ROW_NUMBER() OVER (ORDER BY C.CREATED_AT DESC) AS RN FROM COMPANION_BOARD C JOIN MEMBER M ON C.MEMBER_NO = M.MEMBER_NO WHERE C.STATUS != 'N'
AND (C.TITLE LIKE '%' || #{search} || '%' OR M.NICKNAME LIKE '%' || #{search} || '%')
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.update:
UPDATE COMPANION_BOARD
SET STATUS = 'N', UPDATED_AT = SYSDATE
WHERE COMPANION_NO = #{companionNo}

mapper.select:
SELECT * FROM ( SELECT R.REVIEW_NO AS "reviewNo", R.TITLE AS "title", R.RATING AS "rating", R.STATUS AS "status", TO_CHAR(R.CREATED_AT, 'YYYY-MM-DD') AS "createdAt", M.NICKNAME AS "authorNickname", M.MEMBER_NO AS "memberNo", ROW_NUMBER() OVER (ORDER BY R.CREATED_AT DESC) AS RN FROM COMPANION_REVIEW R JOIN MEMBER M ON R.MEMBER_NO = M.MEMBER_NO WHERE R.STATUS != 'N'
AND (R.TITLE LIKE '%' || #{search} || '%' OR M.NICKNAME LIKE '%' || #{search} || '%')
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.update:
UPDATE COMPANION_REVIEW
SET STATUS = 'N', UPDATED_AT = SYSDATE
WHERE REVIEW_NO = #{reviewNo}

mapper.select:
SELECT * FROM ( SELECT A.ACCOMMODATION_NO AS "accommodationNo", A.NAME AS "name", A.REGION AS "region", A.ACCOMMODATION_TYPE AS "accommodationType", A.STATUS AS "status", TO_CHAR(A.CREATED_AT, 'YYYY-MM-DD') AS "createdAt", ROW_NUMBER() OVER (ORDER BY A.CREATED_AT DESC) AS RN FROM ACCOMMODATION A WHERE 1=1
AND (A.NAME LIKE '%' || #{search} || '%' OR A.REGION LIKE '%' || #{search} || '%')
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.update:
UPDATE ACCOMMODATION
SET STATUS = #{status}, UPDATED_AT = SYSDATE
WHERE ACCOMMODATION_NO = #{accommodationNo}
